'use client'

import { useContentSelector, useUiSelector } from '@/editor/lib/store'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Upload, Sparkles, X, Check } from 'lucide-react'
import { useState, useRef } from 'react'
import { cn } from '@/lib/utils'
import { useIsMobile } from '@/hooks/use-mobile'
import { MobileBottomSheet } from '../mobile/mobile-bottom-sheet'

interface MediaLibraryModalProps {
  mode?: 'select' | 'manage'
  onSelectImage?: (url: string) => void
}

export function MediaLibraryModal({ mode = 'manage', onSelectImage }: MediaLibraryModalProps) {
  const { isMediaLibraryOpen, toggleMediaLibrary } = useUiSelector((state) => ({
    isMediaLibraryOpen: state.isMediaLibraryOpen,
    toggleMediaLibrary: state.toggleMediaLibrary,
  }))
  const { mediaLibrary, addMediaImage, removeMediaImage } = useContentSelector((state) => ({
    mediaLibrary: state.mediaLibrary,
    addMediaImage: state.addMediaImage,
    removeMediaImage: state.removeMediaImage,
  }))

  const [urlInput, setUrlInput] = useState('')
  const [selectedImageUrl, setSelectedImageUrl] = useState<string | null>(null)

  const fileInputRef = useRef<HTMLInputElement>(null)
  const isMobile = useIsMobile()

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (!files) return

    Array.from(files).forEach((file) => {
      const reader = new FileReader()
      reader.onload = (event) => {
        const url = event.target?.result as string
        addMediaImage({
          id: `img-${Date.now()}-${Math.random()}`,
          url,
          name: file.name,
          uploadedAt: new Date(),
        })
      }
      reader.readAsDataURL(file)
    })

    if (fileInputRef.current) fileInputRef.current.value = ''
  }

  const handleAddUrl = () => {
    if (!urlInput.trim()) return

    addMediaImage({
      id: `img-${Date.now()}-${Math.random()}`,
      url: urlInput,
      name: 'External Image',
      uploadedAt: new Date(),
    })
    setUrlInput('')
  }

  const handleSelectImage = (url: string) => {
    if (mode === 'select') setSelectedImageUrl(url)
  }

  const handleConfirmSelection = () => {
    if (selectedImageUrl && onSelectImage) {
      onSelectImage(selectedImageUrl)
      setSelectedImageUrl(null)
      toggleMediaLibrary()
    }
  }

  // --- Контент (без обвязки Dialog / BottomSheet) ---
  const uploadRow = (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
      {/* Upload button */}
      <div>
        <Label className="text-xs font-medium text-slate-900 uppercase tracking-wider mb-2 block">Upload Image</Label>

        <Button
          variant="outline"
          className="w-full h-24 border border-dashed border-slate-200 rounded-2xl bg-slate-50 hover:bg-slate-100 hover:border-slate-300 transition-all text-slate-500 hover:text-slate-900"
          onClick={() => fileInputRef.current?.click()}
        >
          <div className="flex flex-col items-center gap-2">
            <Upload className="h-5 w-5" />
            <span className="text-xs font-medium">Click to upload</span>
          </div>
        </Button>

        <input
          ref={fileInputRef}
          type="file"
          multiple
          accept="image/*,image/svg+xml"
          className="hidden"
          onChange={handleFileUpload}
        />
      </div>

      {/* Add URL */}
      <div>
        <Label className="text-xs font-medium text-slate-900 uppercase tracking-wider mb-2 block">Add from URL</Label>

        <Input
          placeholder="https://example.com/image.jpg"
          value={urlInput}
          onChange={(e) => setUrlInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleAddUrl()}
          className="rounded-xl border-slate-200 focus-visible:ring-slate-900 h-10"
        />

        <Button
          onClick={handleAddUrl}
          className="w-full mt-3 flex items-center justify-center gap-2 bg-slate-900 hover:bg-slate-800 text-white rounded-full h-10 shadow-lg shadow-slate-900/10 transition-all hover:scale-[1.02] active:scale-[0.98]"
        >
          <Sparkles className="h-4 w-4" />
          <span className="text-xs font-medium">Add Image</span>
        </Button>
      </div>
    </div>
  )

  const galleryArea = (
    <div className="flex-1 min-h-0 flex flex-col mt-2">
      <Label className="text-xs font-medium text-slate-900 uppercase tracking-wider mb-3 block">
        Your Library <span className="text-slate-400 ml-1">({mediaLibrary.length})</span>
      </Label>

      <div
        className="flex-1 min-h-0 overflow-y-auto border border-slate-100 rounded-2xl p-4 bg-slate-50/50"
        // Управление моментом начала скролла:
        // на мобилке скролл начнётся раньше — ограничиваем высоту
        style={{ maxHeight: isMobile ? '45vh' : undefined }}
      >
        {mediaLibrary.length === 0 ? (
          <div className="flex items-center justify-center h-40 text-slate-400">
            <div className="text-center">
              <div className="h-12 w-12 bg-white rounded-full flex items-center justify-center mx-auto mb-3 shadow-sm border border-slate-100">
                <Upload className="h-5 w-5 text-slate-300" />
              </div>
              <p className="text-sm font-medium text-slate-500">No images yet</p>
              <p className="text-xs text-slate-400 mt-1">Upload or add via URL</p>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
            {mediaLibrary.map((image) => (
              <div
                key={image.id}
                className={cn(
                  'relative group rounded-xl overflow-hidden border cursor-pointer aspect-square transition-all duration-300',
                  selectedImageUrl === image.url
                    ? 'border-slate-900 ring-2 ring-slate-900 ring-offset-2'
                    : 'border-slate-200 hover:border-slate-300 hover:shadow-md hover:-translate-y-0.5 bg-white'
                )}
                onClick={() => handleSelectImage(image.url)}
              >
                <img
                  src={image.url}
                  alt={image.name}
                  className="w-full h-full object-cover"
                  loading="lazy"
                />

                {selectedImageUrl === image.url && mode === 'select' && (
                  <div className="absolute inset-0 bg-slate-900/20 flex items-center justify-center backdrop-blur-[1px]">
                    <div className="bg-slate-900 text-white rounded-full p-2 shadow-lg transform scale-100 transition-transform">
                      <Check className="h-4 w-4" />
                    </div>
                  </div>
                )}

                {/* Minimal delete button */}
                {mode === 'manage' && (
                  <button
                    onClick={(e) => {
                      e.stopPropagation()
                      removeMediaImage(image.id)
                    }}
                    className="
                      absolute top-2 right-2 
                      bg-white/90 hover:bg-red-50 
                      text-slate-400 hover:text-red-500
                      rounded-full 
                      p-1.5 
                      shadow-sm
                      opacity-0 group-hover:opacity-100 transition-all transform scale-90 group-hover:scale-100
                    "
                    aria-label="Delete image"
                  >
                    <X className="h-3.5 w-3.5" />
                  </button>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )

  const actionsBar = (
    <div className="hidden md:flex justify-end gap-3 pt-6 border-t border-slate-100 bg-transparent">
      <Button 
        variant="ghost" 
        onClick={toggleMediaLibrary}
        className="rounded-full text-slate-500 hover:text-slate-900 hover:bg-slate-100/50"
      >
        {mode === 'select' ? 'Cancel' : 'Close'}
      </Button>

      {mode === 'select' && selectedImageUrl && (
        <Button 
            onClick={handleConfirmSelection} 
            className="rounded-full bg-slate-900 text-white hover:bg-slate-800 shadow-lg shadow-slate-900/20 px-6 transition-all hover:scale-105 active:scale-95"
        >
          Select Image
        </Button>
      )}
    </div>
  )

  // --- MOBILE: MobileBottomSheet (использует тот же контент) ---
  if (isMobile) {
    return (
      <MobileBottomSheet
        isOpen={isMediaLibraryOpen}
        onClose={toggleMediaLibrary}
        title="Media Library"
      >
        <div className="flex flex-col h-full min-h-0">
          {/* Верхняя панель (заголовок внутри bottom sheet) */}
          <div className="px-4 pb-2 border-b">
            <div className="text-lg font-semibold">Media Library</div>
            <div className="text-sm text-muted-foreground">
              {mode === 'select' ? 'Выберите изображение для галереи' : 'Загрузите или управляйте изображениями'}
            </div>
          </div>

          {/* Контент: загрузка + галерея */}
          <div className="pt-4 overflow-auto flex-1 min-h-0">
            <div className="flex flex-col gap-4">
              {uploadRow}
              {galleryArea}
            </div>
          </div>

          {/* Закреплённые кнопки внизу */}
          <div>
            {actionsBar}
          </div>
        </div>
      </MobileBottomSheet>
    )
  }

  // --- DESKTOP: Dialog ---
  return (
    <Dialog open={isMediaLibraryOpen} onOpenChange={toggleMediaLibrary}>
      <DialogContent className="sm:max-w-2xl max-h-[85vh] flex flex-col min-h-0 bg-white/95 backdrop-blur-xl border-slate-100 shadow-2xl p-8 gap-0">
        <DialogHeader className="pb-6">
          <DialogTitle className="text-xl font-medium text-slate-900 tracking-tight">
            Media Library
          </DialogTitle>
          <DialogDescription className="text-slate-500">
            {mode === 'select'
              ? 'Select an image for your gallery'
              : 'Upload and manage your images'}
          </DialogDescription>
        </DialogHeader>

        {/* MAIN CONTENT */}
        <div className="flex flex-col gap-6 flex-1 min-h-0 px-0">
          {uploadRow}
          {galleryArea}
        </div>

        {/* Bottom buttons */}
        <div className="px-0">{actionsBar}</div>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { useContentSelector, useUiSelector } from '@/editor/lib/store'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Check, Upload } from 'lucide-react'
import { useState, useRef } from 'react'
import { cn } from '@/lib/utils'

interface MediaPickerModalProps {
  onSelectImage?: (url: string) => void
  onSelectImages?: (urls: string[]) => void
}

export function MediaPickerModal({ onSelectImage, onSelectImages }: MediaPickerModalProps) {
  const { mediaLibrary, addMediaImage } = useContentSelector((state) => ({
    mediaLibrary: state.mediaLibrary,
    addMediaImage: state.addMediaImage,
  }))
  const { isMediaPickerOpen, toggleMediaPicker } = useUiSelector((state) => ({
    isMediaPickerOpen: state.isMediaPickerOpen,
    toggleMediaPicker: state.toggleMediaPicker,
  }))
  const [selectedUrls, setSelectedUrls] = useState<string[]>([])
  const fileInputRef = useRef<HTMLInputElement>(null)

  const isMultiSelect = !!onSelectImages

  const handleConfirm = () => {
    if (selectedUrls.length > 0) {
      if (isMultiSelect && onSelectImages) {
        onSelectImages(selectedUrls)
      } else if (!isMultiSelect && onSelectImage) {
        onSelectImage(selectedUrls[0])
      }
    }

    setSelectedUrls([])
    toggleMediaPicker()
  }

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (!files) return

    Array.from(files).forEach((file) => {
      const reader = new FileReader()
      reader.onload = (event) => {
        const url = event.target?.result as string
        addMediaImage({
          id: `img-${Date.now()}-${Math.random()}`,
          url,
          name: file.name,
          uploadedAt: new Date(),
        })
      }
      reader.readAsDataURL(file)
    })

    if (fileInputRef.current) fileInputRef.current.value = ''
  }

  return (
    <Dialog open={isMediaPickerOpen} onOpenChange={toggleMediaPicker}>
      <DialogContent className="sm:max-w-2xl max-h-[80vh] flex flex-col bg-white/95 backdrop-blur-xl border-slate-100 shadow-2xl p-8 gap-0">
        <DialogHeader className="pb-6 flex flex-row items-center justify-between">
          <div>
            <DialogTitle className="text-xl font-medium text-slate-900 tracking-tight">Select Image</DialogTitle>
            <DialogDescription className="text-slate-500">
              Choose one of your previously uploaded photos.
            </DialogDescription>
          </div>
          <Button
            variant="outline"
            size="sm"
            className="gap-2 rounded-full"
            onClick={() => fileInputRef.current?.click()}
          >
            <Upload className="h-4 w-4" />
            Upload
          </Button>
          <input
            ref={fileInputRef}
            type="file"
            multiple
            accept="image/*,image/svg+xml"
            className="hidden"
            onChange={handleFileUpload}
          />
        </DialogHeader>

        {/* Scrollable area */}
        <div className="flex-1 min-h-0 overflow-y-auto rounded-2xl border border-slate-100 p-4 bg-slate-50/50">
          {mediaLibrary.length === 0 ? (
            <div className="flex items-center justify-center h-40 text-slate-400 text-sm font-medium">
              No images yet. Upload images first.
            </div>
          ) : (
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
              {mediaLibrary.map((image) => (
                <button
                  key={image.id}
                  type="button"
                  onClick={() => {
                    setSelectedUrls((prev) => {
                      // В режиме одиночного выбора просто заменяем текущее значение
                      if (!isMultiSelect) {
                        return [image.url]
                      }

                      // В мульти-режиме переключаем выбранность
                      if (prev.includes(image.url)) {
                        return prev.filter((u) => u !== image.url)
                      }
                      return [...prev, image.url]
                    })
                  }}
                  className={cn(
                    'relative aspect-square rounded-xl overflow-hidden border cursor-pointer transition-all duration-300',
                    selectedUrls.includes(image.url)
                      ? 'border-slate-900 ring-2 ring-slate-900 ring-offset-2'
                      : 'border-slate-200 hover:border-slate-300 hover:shadow-md hover:-translate-y-0.5 bg-white'
                  )}
                >
                  <img
                    src={image.url || "/placeholder.svg"}
                    alt={image.name}
                    className="w-full h-full object-cover"
                  />
                  {selectedUrls.includes(image.url) && (
                    <div className="absolute inset-0 bg-slate-900/20 flex items-center justify-center backdrop-blur-[1px]">
                      <div className="bg-slate-900 text-white rounded-full p-2 shadow-lg transform scale-100 transition-transform">
                        <Check className="h-4 w-4" />
                      </div>
                    </div>
                  )}
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="flex justify-end gap-3 pt-6 border-t border-slate-100 mt-0">
          <Button 
            variant="ghost" 
            onClick={toggleMediaPicker}
            className="rounded-full text-slate-500 hover:text-slate-900 hover:bg-slate-100/50"
          >
            Cancel
          </Button>
          <Button 
            onClick={handleConfirm} 
            disabled={selectedUrls.length === 0}
            className="rounded-full bg-slate-900 text-white hover:bg-slate-800 shadow-lg shadow-slate-900/20 px-6 transition-all hover:scale-105 active:scale-95 disabled:opacity-50 disabled:hover:scale-100"
          >
            {isMultiSelect ? 'Use Selected Images' : 'Use Selected'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { motion } from 'framer-motion'
import { cn } from '@/lib/utils'
import type { DecorationElement } from '@/editor/lib/types'
import { useCallback, useMemo, useRef } from 'react'
import { useThemeSelector, useUiSelector } from '@/editor/lib/store'
import { DecorationsDndHandle } from './decorations-dnd-handle'
import { useDecorationDnd } from '@/editor/hooks/use-decoration-dnd'
import { DecorationsFloatingMenu } from './decorations-floating-menu'

interface DecorationsLayerProps {
  decorations: DecorationElement[]
  animation?: 'none' | 'fade' | 'slide-up' | 'slide-down' | string
}

const getAnimationVariants = (animation?: string) => {
  switch (animation) {
    case 'slide-up':
      return {
        initial: { opacity: 0, y: 30 },
        animate: { opacity: 1, y: 0 },
      }
    case 'slide-down':
      return {
        initial: { opacity: 0, y: -30 },
        animate: { opacity: 1, y: 0 },
      }
    case 'fade':
    case 'none':
    default:
      return {
        initial: { opacity: 0 },
        animate: { opacity: 1 },
      }
  }
}

const getSizeClass = (size: string | undefined) => {
  switch (size) {
    case 'small':
      return 'w-[100px] h-[100px]'
    case 'medium':
      return 'w-[150px] h-[150px]'
    case 'large':
      return 'w-[200px] h-[200px]'
    case 'xlarge':
      return 'w-[300px] h-[300px]'
    default:
      return size || 'w-40 h-40'
  }
}

const getBaseSizePx = (size: string | undefined) => {
  switch (size) {
    case 'small':
      return 100
    case 'medium':
      return 150
    case 'large':
      return 200
    case 'xlarge':
      return 300
    default:
      return 160
  }
}

export function DecorationsLayer({ decorations, animation }: DecorationsLayerProps) {
  const animationVariants = getAnimationVariants(animation)

  const boundsRef = useRef<HTMLDivElement>(null)
  const { selectedDecorationId, deviceView } = useUiSelector((state) => ({
    selectedDecorationId: state.selectedDecorationId,
    deviceView: state.deviceView,
  }))
  const { updateDecoration, removeDecoration } = useThemeSelector((state) => ({
    updateDecoration: state.updateDecoration,
    removeDecoration: state.removeDecoration,
  }))

  const responsiveFactor = useMemo(() => {
    switch (deviceView) {
      case 'mobile':
        return 0.72
      case 'tablet':
        return 0.86
      case 'desktop':
      case 'fullscreen':
      default:
        return 1
    }
  }, [deviceView])

  const getSelectedElement = useCallback(() => {
    const container = boundsRef.current
    if (!container || !selectedDecorationId) return null
    return container.querySelector(`[data-decoration-id="${selectedDecorationId}"]`) as HTMLElement | null
  }, [selectedDecorationId])

  const selectedDecoration = useMemo(
    () => (selectedDecorationId ? decorations.find((d) => d.id === selectedDecorationId) : undefined),
    [decorations, selectedDecorationId],
  )

  const selectedDecorationSizePx = useMemo(() => {
    if (!selectedDecoration) return 0
    const baseScale = selectedDecoration.scale ?? 1
    const effectiveScale = (selectedDecoration.responsiveScale ? responsiveFactor : 1) * baseScale
    return Math.max(16, Math.round(getBaseSizePx(selectedDecoration.size) * effectiveScale))
  }, [responsiveFactor, selectedDecoration])

  const selectedDecorationMenuOffsets = useMemo(() => {
    if (!selectedDecorationSizePx) return { offsetX: 0, offsetY: 0 }
    return {
      // center under the decoration
      offsetX: selectedDecorationSizePx / 2,
      // below the decoration with a small gap
      offsetY: selectedDecorationSizePx + 12,
    }
  }, [selectedDecorationSizePx])

  const {
    dragControls,
    dragX,
    dragY,
    dragConstraints,
    startDragFromPointerEvent,
    commitDragPosition,
  } = useDecorationDnd({
    selectedDecorationId,
    boundsRef,
    getSelectedElement,
    onCommitPercentPosition: (id, position) => updateDecoration(id, { position }),
  })

  // IMPORTANT: keep this AFTER hooks.
  // React can throw an internal error when a component sometimes returns null
  // before running hooks (e.g. decorations.length === 0) and later starts
  // running hooks when data appears.
  if (!decorations.length) return null

  return (
    <>
      {/* Constraints wrapper (not interactive) */}
      <div ref={boundsRef} className="absolute inset-0 pointer-events-none">
        {decorations.map((decoration, index) => {
          const baseScale = decoration.scale ?? 1
          const effectiveScale = (decoration.responsiveScale ? responsiveFactor : 1) * baseScale

          return (
            <motion.div
            key={decoration.id || `decoration-${index}`}
            data-decoration-id={decoration.id || undefined}
            initial={animationVariants.initial}
            animate={
              decoration.id && decoration.id === selectedDecorationId
                ? { opacity: decoration.opacity }
                : { ...animationVariants.animate, opacity: decoration.opacity }
            }
            transition={{ duration: 0.8, delay: index * 0.15 }}
            className={cn(
              'absolute pointer-events-none',
              decoration.scale == null ? getSizeClass(decoration.size) : undefined,
            )}
            style={{
              top: decoration.position?.top || 'auto',
              bottom: decoration.position?.bottom || 'auto',
              left: decoration.position?.left || 'auto',
              right: decoration.position?.right || 'auto',
              zIndex: decoration.zIndex || 0,
              x: decoration.id && decoration.id === selectedDecorationId ? dragX : 0,
              y: decoration.id && decoration.id === selectedDecorationId ? dragY : 0,
              ...(decoration.scale != null
                ? {
                    width: `${Math.max(16, Math.round(getBaseSizePx(decoration.size) * effectiveScale))}px`,
                    height: `${Math.max(16, Math.round(getBaseSizePx(decoration.size) * effectiveScale))}px`,
                  }
                : null),
            }}
          >
            <img
              src={typeof decoration.image === 'string' && decoration.image ? decoration.image : '/placeholder.svg'}
              alt=""
              className="w-full h-full object-contain"
            />
          </motion.div>
          )
        })}
      </div>

      {/* Minimal DnD handle: only for selected custom decoration */}
      {selectedDecoration?.id ? (
        <>
          <DecorationsDndHandle
            decoration={selectedDecoration}
            sizePx={selectedDecorationSizePx}
            dragX={dragX}
            dragY={dragY}
            dragControls={dragControls}
            dragConstraints={dragConstraints}
            onStartDrag={startDragFromPointerEvent}
            onCommit={commitDragPosition}
          />

          <DecorationsFloatingMenu
            scale={selectedDecoration.scale ?? 1}
            onScaleChange={(next) => updateDecoration(selectedDecoration.id!, { scale: next })}
            onDelete={() => removeDecoration(selectedDecoration.id!)}
            anchor={selectedDecoration.position}
            x={dragX}
            y={dragY}
            offsetX={selectedDecorationMenuOffsets.offsetX}
            offsetY={selectedDecorationMenuOffsets.offsetY}
            className="-translate-x-1/2"
          />
        </>
      ) : null}
    </>
  )
}

export default DecorationsLayer

"use client"

import { useUiSelector, useThemeSelector } from '@/editor/lib/store'
import { Button } from '@/components/ui/button'
import { decorationPresets, getDecorationById, themeToPreset } from '@/editor/lib/decorations'
import { useState } from 'react'
import { cn } from '@/lib/utils'

interface DecorationsSelectorContentProps {
  onClose?: () => void
}

export function DecorationsSelectorContent({ onClose }: DecorationsSelectorContentProps) {
  const { setPreviewDecorations, clearPreviewDecorations } = useUiSelector((state) => ({
    setPreviewDecorations: state.setPreviewDecorations,
    clearPreviewDecorations: state.clearPreviewDecorations,
  }))

  const { setDecorations, updateThemeCustomization, currentTheme } = useThemeSelector((state) => ({
    setDecorations: state.setDecorations,
    updateThemeCustomization: state.updateThemeCustomization,
    currentTheme: state.currentTheme,
  }))

  const presets = Object.values(decorationPresets)
  const [selected, setSelected] = useState<string | null>(null)

  const applyPreset = (presetId?: string) => {
    if (!presetId) return
    const preset = getDecorationById(presetId) as any

    const coerceImageUrl = (value: unknown) => {
      if (typeof value === 'string') return value
      if (value && typeof value === 'object' && 'url' in value && typeof (value as any).url === 'string') {
        return (value as any).url
      }
      return ''
    }

    const mapped = (preset.elements || []).map((el: any, i: number) => ({
      id: `preset-${presetId}-${i}-${Date.now()}`,
      position: el.position || {},
      image: coerceImageUrl(el.image) || '/placeholder.svg',
      opacity: el.opacity ?? 0.15,
      size: el.size,
      zIndex: el.zIndex || 0,
    }))

    setDecorations(mapped)

    if (preset.backgroundImage) {
      updateThemeCustomization({
        customBackground: preset.backgroundImage.url,
        backgroundImageOpacity: preset.backgroundImage.opacity,
        backgroundImageType: preset.backgroundImage.type,
      })
    }

    clearPreviewDecorations()
    if (onClose) onClose()
  }

  return (
    <div className="space-y-4">
      {/* Выбранный пресет */}
      <div className="text-sm text-muted-foreground">
        {selected ? (
          <span>
            Selected: <span className="text-foreground font-medium">{selected}</span>
          </span>
        ) : (
          <span>No preset selected</span>
        )}
      </div>

      {/* Сетка пресетов */}
      <div className="grid grid-cols-2 gap-3">
        {presets.map((p) => {
          const firstEl = p.elements?.[0]
          const getImgUrl = (img: any) => (typeof img === 'string' ? img : img?.url)
          const thumbnail =
            (firstEl && getImgUrl(firstEl.image)) ||
            p.backgroundImage?.url ||
            '/placeholder.svg'

          const isSelected = selected === p.id

          return (
            <div
              key={p.id}
              className={cn(
                "relative group cursor-pointer rounded-xl overflow-hidden border transition-all duration-300",
                isSelected 
                    ? "border-slate-900 ring-2 ring-slate-900 ring-offset-2" 
                    : "border-slate-200 hover:border-slate-300 hover:shadow-md hover:-translate-y-0.5"
              )}
              onMouseEnter={() => setPreviewDecorations(p)}
              onMouseLeave={() => clearPreviewDecorations()}
              onClick={() => setSelected(p.id)}
            >
              <div className="aspect-square bg-slate-50 relative">
                <img
                  src={thumbnail}
                  alt={p.name}
                  className="w-full h-full object-cover opacity-90 group-hover:opacity-100 transition-opacity"
                />
                <div className="absolute inset-0 bg-linear-to-t from-black/60 to-transparent flex items-end p-3">
                  <span className="text-white text-xs font-medium truncate w-full tracking-wide">
                    {p.name}
                  </span>
                </div>
              </div>
            </div>
          )
        })}
      </div>

      <div className="flex justify-end gap-3 pt-6 border-t border-slate-100">
        {onClose && (
          <Button 
            variant="ghost" 
            onClick={onClose}
            className="rounded-full text-slate-500 hover:text-slate-900 hover:bg-slate-100/50"
          >
            Cancel
          </Button>
        )}
        <Button 
          disabled={!selected} 
          onClick={() => applyPreset(selected!)}
          className="rounded-full bg-slate-900 text-white hover:bg-slate-800 shadow-lg shadow-slate-900/20 px-6 transition-all hover:scale-105 active:scale-95 disabled:opacity-50 disabled:hover:scale-100"
        >
          Apply Preset
        </Button>
      </div>
    </div>
  )
}

"use client"

import { Label } from '@/components/ui/label'
import { Input } from '@/components/ui/input'
